"""Standalone training, validation, candidate prediction and formulation query.

Run without arguments for the GUI. Command-line examples:
  python machine_learning.py train --data Ml-data.csv --output ML_runs
  python machine_learning.py query --results ML_runs/<run directory>

Dependencies: numpy, pandas, scipy, scikit-learn, joblib, matplotlib,
seaborn, Pillow, and Python with tkinter. Original scripts are embedded
verbatim; runtime adaptations only concern paths and optional logo images.
Training retains all original validation settings and can take substantial time.
The query interface searches predicted candidates; it does not retrain models.
"""
from __future__ import annotations

import argparse
import ast
import base64
from datetime import datetime
import hashlib
import importlib.metadata
import json
import os
from pathlib import Path
import platform
import queue
import shutil
import subprocess
import sys
import threading
import traceback

SOURCE_BUNDLE = {'ML-2.py': '', 'elastic_moduluschaxun.py': ''}


def source(name):
    return base64.b64decode(SOURCE_BUNDLE[name]).decode('utf-8-sig')


def training_tree(data_file, output_dir):
    """Adapt only four top-level path assignments in the original script."""
    tree = ast.parse(source('ML-2.py'), filename='ML-2.py')
    paths = {'BASE_DIR': output_dir, 'DATA_FILE': data_file,
             'OUTPUT_DIR': output_dir / 'outdata', 'PREDICTION_OUTPUT_DIR': output_dir}
    for node in tree.body:
        if isinstance(node, ast.Assign):
            for target in node.targets:
                if isinstance(target, ast.Name) and target.id in paths:
                    node.value = ast.parse('Path(' + repr(str(paths[target.id])) + ')', mode='eval').body
    return ast.fix_missing_locations(tree)


def query_tree():
    """Use optional local logos; preserve the original text fallback."""
    class LocalLogos(ast.NodeTransformer):
        def visit_Constant(self, node):
            if isinstance(node.value, str):
                for name in ('logo1.jpg', 'logo2.jpg'):
                    if node.value.replace('\\', '/').endswith('/' + name):
                        return ast.copy_location(ast.Constant(name), node)
            return node
    return ast.fix_missing_locations(LocalLogos().visit(ast.parse(source('elastic_moduluschaxun.py'))))


def train(data_file, output_root):
    data_file = Path(data_file).expanduser().resolve()
    if not data_file.is_file():
        raise FileNotFoundError(data_file)
    directory = Path(output_root).expanduser().resolve() / datetime.now().strftime('%Y%m%d_%H%M%S_%f')
    directory.mkdir(parents=True, exist_ok=False)
    snapshot = directory / 'Ml-data.csv'
    shutil.copy2(data_file, snapshot)
    versions = {}
    for name in ('numpy', 'pandas', 'scipy', 'scikit-learn', 'joblib', 'matplotlib', 'seaborn', 'Pillow'):
        try:
            versions[name] = importlib.metadata.version(name)
        except importlib.metadata.PackageNotFoundError:
            versions[name] = 'not installed'
    manifest = {'status': 'running', 'started_at': datetime.now().astimezone().isoformat(),
                'source_data': str(data_file), 'data_sha256': hashlib.sha256(snapshot.read_bytes()).hexdigest(),
                'python': sys.version, 'platform': platform.platform(), 'dependencies': versions,
                'source_sha256': {k: hashlib.sha256(base64.b64decode(v)).hexdigest() for k, v in SOURCE_BUNDLE.items()}}
    manifest_path = directory / 'run_manifest.json'
    def save_manifest():
        manifest_path.write_text(json.dumps(manifest, ensure_ascii=False, indent=2), encoding='utf-8')
    save_manifest()
    print('RUN_DIRECTORY=' + str(directory), flush=True)
    try:
        import matplotlib
        matplotlib.use('Agg')
        namespace = {'__name__': 'embedded_ml_training', '__file__': str(Path(__file__).resolve())}
        exec(compile(training_tree(snapshot, directory), 'ML-2.py', 'exec'), namespace)
        settings = ('RANDOM_SEED', 'TEST_SIZE', 'STACKING_CV_SPLITS', 'GBR_TUNING_CV_SPLITS',
                    'OUTER_CV_SPLITS', 'RUN_OUTER_CV', 'RIGOROUS_NESTED_TUNING', 'N_JOBS',
                    'TARGET_COLS', 'FEATURE_COLS', 'GBR_PARAM_GRID', 'RIDGE_ALPHA',
                    'RF_N_ESTIMATORS', 'RF_MAX_DEPTH', 'PREDICTION_EXP_ID_START',
                    'PREDICTION_EXP_ID_END', 'PREDICTION_WEIGHT_STEP')
        manifest['settings'] = {name: namespace[name] for name in settings}
        save_manifest()
        namespace['main']()
        required = [directory / 'material_property_predictions.csv']
        required += [directory / 'outdata' / (namespace['safe_filename'](target) + '_堆叠模型.joblib')
                     for target in namespace['TARGET_COLS']]
        missing = [str(path) for path in required if not path.is_file()]
        if missing:
            raise RuntimeError('Missing outputs: ' + ', '.join(missing))
        manifest['status'] = 'complete'
    except BaseException as error:
        manifest.update(status='failed', error=str(error), traceback=traceback.format_exc())
        raise
    finally:
        manifest['finished_at'] = datetime.now().astimezone().isoformat()
        save_manifest()
    return directory


def query(results):
    directory = Path(results).expanduser().resolve()
    if not (directory / 'material_property_predictions.csv').is_file():
        raise FileNotFoundError('Select a directory containing material_property_predictions.csv.')
    previous = Path.cwd()
    try:
        os.chdir(directory)
        exec(compile(query_tree(), 'elastic_moduluschaxun.py', 'exec'),
             {'__name__': '__main__', '__file__': str(Path(__file__).resolve())})
    finally:
        os.chdir(previous)


def gui():
    import tkinter as tk
    from tkinter import ttk, filedialog, messagebox
    root = tk.Tk()
    root.title('Machine learning — training, validation and query')
    root.geometry('960x640')
    frame = ttk.Frame(root, padding=14)
    frame.pack(fill='both', expand=True)
    base = Path(__file__).resolve().parent
    data = tk.StringVar()
    output = tk.StringVar(value=str(base / 'ML_runs'))
    results = tk.StringVar()
    status = tk.StringVar(value='Select the training CSV, or open an existing prediction directory.')
    events = queue.Queue()
    state = {'process': None, 'log': None, 'run': None}

    def field(label, variable, picker, filename_only=False):
        row = ttk.Frame(frame)
        row.pack(fill='x', pady=6)
        ttk.Label(row, text=label, width=20).pack(side='left')
        display = tk.StringVar()
        def refresh(*_):
            display.set((Path(variable.get()).name if filename_only else 'Selected') if variable.get() else '')
        variable.trace_add('write', refresh)
        ttk.Entry(row, textvariable=display, state='readonly').pack(side='left', fill='x', expand=True)
        def choose():
            path = picker()
            if path:
                variable.set(path)
        ttk.Button(row, text='Browse', command=choose).pack(side='left', padx=5)
    ttk.Label(frame, text='1. Training, validation and candidate prediction', font=('', 12, 'bold')).pack(anchor='w')
    field('Training CSV', data, lambda: filedialog.askopenfilename(filetypes=[('CSV', '*.csv')]), filename_only=True)
    field('Output root', output, filedialog.askdirectory)
    ttk.Label(frame, text='Original ML-2 settings are preserved. Each training run creates a separate results folder.').pack(anchor='w')

    def launch(arguments, mode):
        if state['process'] is not None:
            messagebox.showinfo('Running', 'Finish or stop the current operation first.')
            return
        executable = Path(sys.executable)
        if executable.name.lower() == 'pythonw.exe':
            executable = executable.with_name('python.exe')
        try:
            process = subprocess.Popen([str(executable), '-u', '-X', 'utf8', str(Path(__file__).resolve()), *arguments],
                                       stdout=subprocess.PIPE, stderr=subprocess.STDOUT, encoding='utf-8', errors='replace',
                                       creationflags=subprocess.CREATE_NO_WINDOW if os.name == 'nt' else 0)
        except Exception as error:
            messagebox.showerror('Unable to start', str(error))
            return
        state.update(process=process, run=None, log=None)
        status.set('Training and validation are running…' if mode == 'train' else 'Query window is open.')
        def collect():
            for line in process.stdout:
                events.put(('line', line))
            process.stdout.close()
            events.put(('done', (process.wait(), mode)))
        threading.Thread(target=collect, daemon=True).start()

    def start_train():
        if not Path(data.get()).is_file():
            messagebox.showerror('Missing data', 'Select the training CSV first.')
            return
        launch(['train', '--data', data.get(), '--output', output.get()], 'train')
    ttk.Button(frame, text='Train, validate and generate predictions', command=start_train).pack(anchor='w', pady=8)
    ttk.Separator(frame).pack(fill='x', pady=8)
    ttk.Label(frame, text='2. Query candidate formulations', font=('', 12, 'bold')).pack(anchor='w')
    field('Prediction directory', results, filedialog.askdirectory)

    def start_query():
        if not (Path(results.get()) / 'material_property_predictions.csv').is_file():
            messagebox.showerror('Missing predictions', 'Select a folder containing material_property_predictions.csv.')
            return
        launch(['query', '--results', results.get()], 'query')
    ttk.Button(frame, text='Open formulation query', command=start_query).pack(anchor='w', pady=6)

    def stop():
        process = state['process']
        if process is None:
            return
        if not messagebox.askyesno('Stop', 'Stop this operation and its worker processes? Partial results will be retained.'):
            return
        if os.name == 'nt':
            subprocess.run(['taskkill', '/PID', str(process.pid), '/T', '/F'], capture_output=True,
                           creationflags=subprocess.CREATE_NO_WINDOW)
        else:
            process.terminate()
    ttk.Button(frame, text='Stop current operation', command=stop).pack(anchor='w', pady=4)
    ttk.Label(frame, textvariable=status, wraplength=920).pack(anchor='w', pady=6)
    box = ttk.Frame(frame)
    box.pack(fill='both', expand=True)
    log = tk.Text(box, height=12, wrap='word')
    log.pack(side='left', fill='both', expand=True)
    scroll = ttk.Scrollbar(box, command=log.yview)
    scroll.pack(side='right', fill='y')
    log.configure(yscrollcommand=scroll.set)

    def poll():
        for _ in range(300):
            try:
                kind, value = events.get_nowait()
            except queue.Empty:
                break
            if kind == 'line':
                if value.startswith('RUN_DIRECTORY='):
                    state['run'] = Path(value.strip().split('=', 1)[1])
                    state['log'] = (state['run'] / 'training.log').open('a', encoding='utf-8')
                if state['log']:
                    state['log'].write(value)
                    state['log'].flush()
                log.insert('end', value)
                log.see('end')
            else:
                code, mode = value
                if state['log']:
                    state['log'].close()
                state.update(process=None, log=None)
                if mode == 'train' and code == 0:
                    results.set(str(state['run']))
                    status.set('Training completed. The prediction directory is ready for querying.')
                elif code == 0:
                    status.set('Query window closed.')
                else:
                    status.set('Operation did not complete. See the log for details.')
                    if state['run']:
                        path = state['run'] / 'run_manifest.json'
                        manifest = json.loads(path.read_text(encoding='utf-8'))
                        if manifest['status'] == 'running':
                            manifest.update(status='interrupted', finished_at=datetime.now().astimezone().isoformat())
                            path.write_text(json.dumps(manifest, ensure_ascii=False, indent=2), encoding='utf-8')
        root.after(100, poll)
    def close():
        if state['process'] is not None:
            messagebox.showinfo('Operation running', 'Stop the current operation before closing this window.')
            return
        root.destroy()
    root.protocol('WM_DELETE_WINDOW', close)
    root.after(100, poll)
    root.mainloop()


def main():
    parser = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    commands = parser.add_subparsers(dest='command')
    training = commands.add_parser('train', help='Run original ML-2 training and prediction')
    training.add_argument('--data', required=True)
    training.add_argument('--output', default=str(Path(__file__).resolve().parent / 'ML_runs'))
    querying = commands.add_parser('query', help='Query an existing prediction table')
    querying.add_argument('--results', required=True)
    args = parser.parse_args()
    if args.command == 'train':
        train(args.data, args.output)
    elif args.command == 'query':
        query(args.results)
    else:
        gui()


if __name__ == '__main__':
    main()
